def corridas_a_su_sesion(apps, schema_editor):
    """Las corridas demostrativas de cada planta pasan a su sesión demostrativa."""
    Orden = apps.get_model('webcitt', 'OrdenProduccion')
    Sesion = apps.get_model('webcitt', 'SesionERP')
    for unidad_id in Orden.objects.filter(demostrativa=True, sesion=None).values_list('unidad_id', flat=True).distinct():
        sesion = Sesion.objects.filter(unidad_id=unidad_id, tipo='demostrativa').first()
        if sesion is None:
            sesion = Sesion.objects.create(unidad_id=unidad_id, tipo='demostrativa', nombre='Corridas demostrativas')
            sesion.codigo = f'SE{unidad_id:03d}-{sesion.pk:05d}'
            sesion.save(update_fields=['codigo'])
        Orden.objects.filter(unidad_id=unidad_id, demostrativa=True, sesion=None).update(sesion=sesion)


def corridas_sin_sesion(apps, schema_editor):
    apps.get_model('webcitt', 'OrdenProduccion').objects.exclude(sesion=None).update(sesion=None)


